function feedHTML(){const l=feedList(),labels=[['all','For You'],['following','Following'],['trending','Trending'],['host','Featured'],['uploads','Creators']];
 return `<div id="feed-shell"><div class="watch-toolbar"><div class="watch-title"><span class="eyebrow">THE VIDEO STAGE</span><h1>In the moment<span>.</span></h1></div><div class="feed-switch" aria-label="Video feeds">${labels.map(([mode,label])=>`<button class="${F.source===mode?'active':''}" ${F.source===mode?'aria-current="true"':''} onclick="switchFeed('${mode}')">${label}</button>`).join('')}</div><button id="discovery-toggle" class="discovery-toggle" onclick="discoveryToggle()" aria-controls="watch-discovery" aria-expanded="false">Explore ↗</button></div>
 <div class="watch-layout"><div class="watch-theater"><div class="theater-label"><span><i></i> ${esc(labels.find(x=>x[0]===F.source)?.[1]||'For You')}</span><span id="watch-position">${l.length?'01 / '+String(l.length).padStart(2,'0'):'YOUR STAGE'}</span></div><div class="feed-stage"><div class="feed-frame"><div id="feed" tabindex="0" aria-label="Scrolling videos">${l.length?l.slice(0,12).map(feedItemHTML).join(''):`<div class="feed-empty"><div class="empty-stage-art" aria-hidden="true"><span>▶</span><i></i><i></i></div><span class="eyebrow">ROOM FOR YOUR STORY</span><h2>${F.source==='following'?'Find your people.':'Make the first moment.'}</h2><p>${F.source==='following'?'Follow creators to see their latest videos here.':'New videos will appear here as the community shares. Yours could be the next discovery.'}</p><div><button onclick="${F.source==='following'?"go('community')":"feedUploadModal()"}">${F.source==='following'?'Discover creators ↗':'＋ Post a video'}</button><button class="g" onclick="go('feed')">↻ Refresh</button></div></div>`}</div><div class="feed-progress"><div id="feed-progressbar"></div></div></div></div><div class="theater-footer"><span>SCROLL TO DISCOVER <span>↓</span></span><div class="theater-shortcuts"><kbd>↑</kbd><kbd>↓</kbd><span>Browse</span><kbd>SPACE</kbd><span>Pause</span></div><div class="feed-pager"><button onclick="moveFeed(-1)" id="feed-prev" aria-label="Previous video">↑</button><button onclick="moveFeed(1)" id="feed-next" aria-label="Next video">↓</button></div></div></div>
 <button class="discovery-scrim" onclick="discoveryToggle(false)" aria-label="Close discovery"></button><aside class="watch-discovery" id="watch-discovery" aria-label="Video and music discovery"><div class="discovery-heading"><div><span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h2>Off the main stage.</h2></div><button id="discovery-close" onclick="discoveryToggle(false)" aria-label="Close discovery">✕</button></div><div class="discovery-tabs" role="tablist" aria-label="Discovery"><button role="tab" id="next-tab" aria-controls="next-panel" aria-selected="true" class="active" data-discovery-tab="next" onclick="discoveryTab('next')">Up next</button><button role="tab" id="sounds-tab" aria-controls="sounds-panel" aria-selected="false" data-discovery-tab="sounds" onclick="discoveryTab('sounds')">The sounds</button></div><div class="discovery-body"><div id="next-panel" role="tabpanel" aria-labelledby="next-tab" data-discovery-panel="next"><div id="feed-queue" class="feed-queue"></div></div><div id="sounds-panel" role="tabpanel" aria-labelledby="sounds-tab" data-discovery-panel="sounds" hidden>${watchSoundMarkup()}</div><div class="discovery-region"><span>EVERY CORNER HAS A SOUND.</span><button onclick="go('pulse')">Explore Mzansi Pulse ↗</button></div><div class="discovery-genres">${S.meta.genres.slice(0,6).map(g=>`<button onclick="go('discover','${g}')">${esc(g)}</button>`).join('')}</div></div><button class="discovery-create" onclick="createMenu()"><span>＋</span><span><b>Your moment belongs here.</b><small>Create your next drop</small></span>↗</button></aside></div></div>`;
}
function pauseFeed(){document.querySelectorAll('#feed video').forEach(v=>v.pause());}
function feedReset(){pauseFeed();F.active=-1;const a=$('#app');if(!a||!$('#feed-shell'))return;a.innerHTML=`<div class="pg">${feedHTML()}</div>`;feedInitialize();}
// Render the feed progressively: 12 videos initially, adding batches as the viewer moves.
// At no point do all hundreds of media elements have to exist in the DOM.
function ensureFeedRendered(requested){
 const root=$('#feed');if(!root)return;
 const videos=feedList(),next=Math.min(videos.length,Math.max(F.rendered,requested));
 if(next<=F.rendered)return;
 const doc=document.createDocumentFragment();
 for(let i=F.rendered;i<next;i++){
  const holder=document.createElement('div');holder.innerHTML=feedItemHTML(videos[i],i);
  doc.appendChild(holder.firstElementChild);
 }
 root.appendChild(doc);F.rendered=next;
}
async function switchFeed(mode){if(mode===F.source)return;pauseFeed();F.source=mode;
 try{if(['all','following','trending'].includes(mode)){const selection=await api('/api/video-discover?mode='+({'all':'for-you','following':'following','trending':'trending'}[mode]));F.items=selection.videos||[]}
 else F.items=F.baseline;
 feedReset()}catch(e){toast('Unable to load the selected feed');F.source='all';F.items=F.baseline;feedReset()}}

function primeFeed(index){const entry=feedList()[index],el=$(`#feed .fi[data-index="${index}"] video`);if(!entry||!el||el.dataset.loaded)return;
 el.poster=entry.thumbnail||'/video-placeholder.svg';el.src=entry.src;el.dataset.loaded='1';el.muted=F.muted;el.preload=index===F.active?'auto':'metadata';el.load();}
function feedActivate(index){const l=feedList();if(index<0||index>=l.length||!$('#feed'))return;ensureFeedRendered(index+9);if(index===F.active)return;
 F.active=index;const sections=Array.from(document.querySelectorAll('#feed .fi'));
 sections.forEach((sec,i)=>{const v=sec.querySelector('video');if(i!==index){v.pause();sec.classList.remove('paused')}
  if(Math.abs(i-index)>2&&v.dataset.loaded){v.removeAttribute('src');delete v.dataset.loaded;v.load();}});
 primeFeed(index);primeFeed(index-1);primeFeed(index+1);const sec=sections[index],v=sec.querySelector('video');v.muted=F.muted;
 v.play().then(()=>sec.classList.remove('paused')).catch(()=>sec.classList.add('paused'));
 v.ontimeupdate=()=>{if(F.active===index&&v.duration&&$('#feed-progressbar'))$('#feed-progressbar').style.width=v.currentTime/v.duration*100+'%';if(!sec.dataset.viewCounted&&v.currentTime>=Math.min(5,(v.duration||10)*.6)){sec.dataset.viewCounted='1';api('/api/video-view',{b:{key:l[index].key}}).catch(()=>{})}};
 if(l[index].source==='artist'&&!sec.dataset.counted){sec.dataset.counted='1';fetch('/api/play',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:l[index].id})}).catch(()=>{})}
 if($('#feed-progressbar'))$('#feed-progressbar').style.width='0%';
 if($('#feed-prev'))$('#feed-prev').disabled=index===0;if($('#feed-next'))$('#feed-next').disabled=index===l.length-1;
 if($('#watch-position'))$('#watch-position').textContent=String(index+1).padStart(2,'0')+' / '+String(l.length).padStart(2,'0');feedQueue();}
function feedInitialize(){const f=$('#feed');if(!f)return;F.active=-1;F.rendered=Math.min(12,feedList().length);if(!feedList().length){feedQueue();return}
 let ticking=false;f.addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{ticking=false;const index=Math.min(feedList().length-1,Math.max(0,Math.round(f.scrollTop/Math.max(1,f.clientHeight))));feedActivate(index)})},{passive:true});feedActivate(0);if(F.pendingKey){const key=F.pendingKey;F.pendingKey=null;const target=feedList().findIndex(v=>v.key===key);if(target>=0){ensureFeedRendered(target+9);f.scrollTop=target*f.clientHeight;feedActivate(target)}else toast('This video is no longer available')}}
function feedQueue(){const q=$('#feed-queue');if(!q)return;const l=feedList();if(!l.length){q.innerHTML='<div class="discovery-empty"><span>↗</span><h3>Discover your people.</h3><p>The next video is on its way. Meet creators while you wait.</p><button onclick="go(\'community\')">Meet the community ↗</button></div>';return}
 const a=Math.max(0,Math.min(F.active-1,l.length-5)),b=Math.min(l.length,a+6);
 q.innerHTML=l.slice(a,b).map((v,k)=>{const i=k+a;return `<button class="feed-qitem ${i===F.active?'active':''}" onclick="discoveryToggle(false);jumpFeed(${i})"><span class="qthumb" aria-hidden="true"><img loading="lazy" decoding="async" src="${esc(v.thumbnail||'/video-placeholder.svg')}" alt=""></span><span style="min-width:0;flex:1"><span class="qname" style="display:block">${esc(v.title)}</span><span class="qsub" style="display:block">${v.source==='host'?'Mzansi Beats':esc(v.creator||'Creator')}</span></span></button>`}).join('');}
function jumpFeed(index){const f=$('#feed');if(!f||index<0||index>=feedList().length)return;ensureFeedRendered(index+9);f.scrollTo({top:index*f.clientHeight,behavior:'smooth'});if(index===F.active){const v=f.querySelectorAll('video')[index];if(v&&v.paused)v.play().catch(()=>{})}}
function moveFeed(dir){jumpFeed(Math.min(feedList().length-1,Math.max(0,F.active+dir)))}
function toggleFeedPlay(video){const s=video.closest('.fi');if(video.paused){video.play().then(()=>s.classList.remove('paused')).catch(()=>toast('Cannot play this video in your browser'))}else{video.pause();s.classList.add('paused')}}
function feedToggleSound(){F.muted=!F.muted;document.querySelectorAll('#feed video').forEach(v=>{v.muted=F.muted});document.querySelectorAll('.feed-volume').forEach(b=>b.textContent=F.muted?'🔇':'🔊');}
document.addEventListener('visibilitychange',()=>{
 const player=$(`#feed .fi[data-index="${F.active}"] video`);
 if(!player)return;
 if(document.hidden){player.dataset.wasPlaying=player.paused?'0':'1';player.pause()}
 else if(player.dataset.wasPlaying==='1'&&S.route[0]==='feed'){player.play().catch(()=>{})}
});
function feedVideoError(v){v.closest('.fi').classList.add('failed')}
function feedFullscreen(){const v=document.querySelector(`#feed .fi[data-index="${F.active}"] video`);if(!v)return;const fn=v.requestFullscreen||v.webkitEnterFullscreen;if(fn)fn.call(v);else toast('Fullscreen is not available')}
function feedShare(key){const item=F.items.find(v=>v.key===key);if(!item)return;
 const link=location.origin+'/?v='+encodeURIComponent(key);
 if(navigator.share)navigator.share({title:item.title,text:'Watch on Mzansi Beats',url:link}).catch(()=>{});
 else copyLink(link);
}
async function videoLike(key){if(!S.user)return authModal();try{const r=await api('/api/video-like',{b:{key}}),v=F.items.find(x=>x.key===key);if(v){v.liked=r.liked;v.likes=r.likes}updateVideoButtons(key)}catch(e){toast(e.message)}}
async function videoSave(key){if(!S.user)return authModal();try{const r=await api('/api/video-save',{b:{key}}),v=F.items.find(x=>x.key===key);if(v)v.saved=r.saved;updateVideoButtons(key);toast(r.saved?'Saved to Library':'Removed from saved videos')}catch(e){toast(e.message)}}
function updateVideoButtons(key){const v=F.items.find(x=>x.key===key),index=feedList().findIndex(x=>x.key===key),sec=$(`#feed .fi[data-index="${index}"]`);if(!v||!sec)return;
 const like=sec.querySelector('.social-like'),save=sec.querySelector('.social-save');like.textContent=v.liked?'♥':'♡';like.classList.toggle('on',v.liked);
 save.textContent=v.saved?'▣':'▢';save.classList.toggle('on',v.saved);
 sec.querySelector('.social-like-count').textContent=numFormat(v.likes);sec.querySelector('.social-comment-count').textContent=numFormat(v.comments);
}
let activeVideoComments=null,replyToVideo=null;
function videoCommentMarkup(items,key){const groups=new Map();items.filter(x=>x.p).forEach(x=>{if(!groups.has(x.p))groups.set(x.p,[]);groups.get(x.p).push(x)});
 const render=(c,reply=false)=>`<div class="social-comment ${reply?'reply':''}"><div class="social-comment-main"><div class="social-comment-avatar">${esc((c.name||'M')[0])}</div><div class="social-comment-body"><strong>${esc(c.name)}</strong> <time>${new Date(c.d).toLocaleDateString('en-ZA')}</time><p>${esc(c.text)}</p><div class="social-comment-buttons"><button class="g" onclick="replyVideoComment('${c.id}','${key}')">Reply</button>${c.mine?`<button class="g" onclick="deleteVideoComment('${c.id}','${key}')">Delete</button>`:''}</div></div></div></div>`;
 return items.filter(x=>!x.p).map(c=>render(c)+(groups.get(c.id)||[]).map(x=>render(x,true)).join('')).join('')||'<p class="mu">Start the conversation.</p>';
}
async function openVideoComments(key){const v=F.items.find(x=>x.key===key);if(!v)return;replyToVideo=null;activeVideoComments=key;
 const player=document.querySelector(`#feed .fi[data-index="${F.active}"] video`);if(player)player.pause();
 try{const comments=await api('/api/video-comments?key='+encodeURIComponent(key));
 M(`<div class="social-modal-head"><span class="eyebrow">/ COMMUNITY CONVERSATION</span><h2>${esc(v.title)}</h2><p class="mu">Connect through the moments that matter.</p></div><div id="video-comments" class="social-comments">${videoCommentMarkup(comments,key)}</div><div id="video-reply" class="mu"></div><textarea id="video-comment-text" maxlength="400" rows="3" placeholder="Add a thoughtful comment…"></textarea><div class="social-modal-actions"><button onclick="sendVideoComment('${key}')">Post comment ↗</button><button class="g" onclick="closeM()">Close</button></div>`)}catch(e){toast(e.message)}
}
function replyVideoComment(id,key){replyToVideo=id;const t=$('#video-reply');if(t)t.innerHTML=`Replying to a comment · <button class="g" onclick="replyToVideo=null;$('#video-reply').textContent=''">Cancel</button>`;$('#video-comment-text')?.focus()}
async function sendVideoComment(key){if(!S.user)return authModal();const input=$('#video-comment-text'),text=input&&input.value.trim();if(!text)return toast('Enter a comment');
 try{await api('/api/video-comment',{b:{key,text,parent:replyToVideo}});const v=F.items.find(x=>x.key===key);if(v)v.comments++;updateVideoButtons(key);await openVideoComments(key);toast('Comment published')}catch(e){toast(e.message)}}
async function deleteVideoComment(id,key){if(!confirm('Remove this comment?'))return;try{await api('/api/video-comment?id='+id,{m:'DELETE'});const v=F.items.find(x=>x.key===key);if(v)v.comments=Math.max(0,v.comments-1);updateVideoButtons(key);await openVideoComments(key)}catch(e){toast(e.message)}}
function reportVideo(key){if(!S.user)return authModal();M(`<h3>Report a video</h3><p class="mu">Help keep the community welcoming and safe.</p><select id="report-reason"><option>Spam</option><option>Harassment</option><option>Copyright</option><option>Unsafe content</option><option>Other</option></select><button onclick="sendVideoReport('${key}')">Submit report</button><button class="g" onclick="closeM()">Cancel</button>`)}
async function sendVideoReport(key){try{await api('/api/video-report',{b:{key,reason:$('#report-reason').value}});closeM();toast('Report sent to moderators')}catch(e){toast(e.message)}}

async function moderateSocialVideo(key,hide){try{await api('/api/video-moderate',{b:{key,hide}});toast(hide?'Video hidden':'Video restored');loadVideoReports();loadHiddenVideos()}catch(e){toast(e.message)}}
async function loadHiddenVideos(){try{const items=await api('/api/video-hidden');$('#hidden-videos').innerHTML=items.length?items.map(v=>`<div class="report-row">${esc(v.title)}<button onclick="moderateSocialVideo('${esc(v.key)}',false)">Restore</button></div>`).join(''):'<p class="mu">No hidden videos.</p>'}catch(e){toast(e.message)}}
async function loadPerformance(){
 try{const s=await api('/api/admin/performance'),p=$('#performance-panel');if(!p)return;
  const n=s.optimizer;
  p.innerHTML=`<div class="stat"><div><b>${n.ffmpegAvailable?'Ready':'Optional'}</b>FFmpeg</div><div><b>${n.thumbnailsBuilt}</b>Thumbnails created</div><div><b>${n.converted}</b>Videos optimized</div><div><b>${n.thumbnailQueue+n.conversionQueue}</b>Queue jobs</div></div><p class="mu">Daily database snapshots are kept in data/backups. Video processing runs in the background when FFmpeg is available.</p><button class="g" onclick="loadPerformance()">Refresh status</button>`;
 }catch(e){toast(e.message)}
}
async function loadVideoReports(){try{const items=await api('/api/video-reports');$('#reports-panel').innerHTML=items.length?items.map(r=>`<div class="report-row"><b>${esc(r.reason)}</b> — ${esc(r.video?.title||'Unavailable video')} <button class="g" onclick="viewVideo('${esc(r.key)}')">View</button><button class="g" onclick="moderateSocialVideo('${esc(r.key)}',true)">Hide</button><button onclick="resolveVideoReport('${r.id}')">Resolve</button></div>`).join(''):'<p class="mu">No open reports.</p>'}catch(e){toast(e.message)}}
async function resolveVideoReport(id){try{await api('/api/video-reports/resolve',{b:{id}});loadVideoReports()}catch(e){toast(e.message)}}
async function moderateVideo(id){try{await api('/api/community-video/moderate',{b:{id}});toast('Video visibility changed');go('admin')}catch(e){toast(e.message)}}
function feedDelete(id){if(!confirm('Delete this video from Mzansi Beats?'))return;
 api('/api/community-video?id='+encodeURIComponent(id),{m:'DELETE'}).then(()=>{toast('Video deleted');go('feed')}).catch(e=>toast(e.message));}
function feedUploadModal(){if(!S.user){toast('Create a free account or sign in first');return authModal(1)}
 M(`<h2>Publish a video</h2><p class="mu">Your video will be visible to everyone on Mzansi Beats.</p>
 <label class="mu">Video title</label><input id="fut" maxlength="100" placeholder="Give your video a title">
 <label class="mu">Link a song (optional — adds attribution, does not replace video audio)</label><select id="video-sound-select"><option value="">No linked sound</option></select><label class="mu">Choose a video (MP4 or WebM, max 250 MB)</label><input id="fum" type="file" accept=".mp4,.webm,.mov,.m4v,video/mp4,video/webm,video/quicktime">
 <div class="prog"><div id="fupg"></div></div><div id="fus" class="mu"></div>
 <button id="fub" onclick="doFeedUpload()">＋ Publish for everyone</button><button class="g" onclick="closeM()">Cancel</button>`);populateVideoSounds('video-sound-select');}
function doFeedUpload(){const file=$('#fum').files[0],title=$('#fut').value.trim();
 if(!file||!title)return toast('Choose a video and enter its title');
 if(file.size>250*1024*1024)return toast('Maximum video size is 250 MB');
 const ext='.'+file.name.split('.').pop().toLowerCase();if(!['.mp4','.webm','.mov','.m4v'].includes(ext))return toast('Use MP4 or WebM for best compatibility');
 const x=new XMLHttpRequest();x.open('POST','/api/community-video?title='+encodeURIComponent(title)+'&ext='+encodeURIComponent(ext)+'&soundId='+encodeURIComponent($('#video-sound-select')?.value||''));
 x.setRequestHeader('Authorization','Bearer '+S.tok);x.setRequestHeader('Content-Type','application/octet-stream');
 $('#fub').disabled=true;$('#fus').textContent='Publishing your video…';
 x.upload.onprogress=e=>{if(e.lengthComputable){const n=Math.round(e.loaded/e.total*100);$('#fupg').style.width=n+'%';$('#fus').textContent=n+'% uploaded'}};
 x.onload=()=>{let msg={};try{msg=JSON.parse(x.responseText)}catch(e){}if(x.status===201){closeM();F.source='all';toast('Video published! Processing for smoother playback may continue in the background.');go('feed')}else{$('#fus').textContent=msg.error||'Upload failed';$('#fub').disabled=false}};
 x.onerror=()=>{$('#fus').textContent='Connection interrupted';$('#fub').disabled=false};x.send(file);
}
async function populateVideoSounds(id,selected=''){
 const select=document.getElementById(id);if(!select)return;
 try{const tracks=await api('/api/music-library');if(!document.getElementById(id))return;
 select.innerHTML='<option value="">No linked song</option>'+tracks.map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.title)} — ${esc(t.artist)}</option>`).join('');
 }catch(e){select.innerHTML='<option value="">Songs unavailable</option>'}
}
function linkVideoSound(key){if(!S.user)return authModal();
 M(`<span class="eyebrow">/ MUSIC × VIDEO</span><h2>Link music to your video</h2><p class="mu">This adds a track credit and a discovery link. It does not change the video's audio.</p><label class="mu" for="video-sound-edit">Choose a song</label><select id="video-sound-edit"><option value="">No linked song</option></select><button onclick="saveVideoSound('${key}')">Save music link</button><button class="g" onclick="closeM()">Cancel</button>`);
 populateVideoSounds('video-sound-edit',F.items.find(x=>x.key===key)?.linkedSound?.id||'');
}
async function saveVideoSound(key){try{const d=await api('/api/video-sound',{b:{key,trackId:$('#video-sound-edit').value}});
 const v=F.items.find(x=>x.key===key);if(v)v.linkedSound=d.track;const original=F.baseline.find(x=>x.key===key);if(original)original.linkedSound=d.track;
 closeM();feedReset();toast('Music link updated');}catch(e){toast(e.message)}}
async function clearVideoHistory(){if(!confirm('Clear your personal watch history? This will also reset watch-based recommendations.'))return;
 try{await api('/api/video-history',{m:'DELETE'});toast('History cleared');go('history')}catch(e){toast(e.message)}}
document.addEventListener('keydown',e=>{if(S.route[0]!=='feed'||$('#modal').classList.contains('show')||document.body.classList.contains('discovery-open'))return;
 const tag=(e.target.tagName||'').toLowerCase();if(['input','textarea','select'].includes(tag)||e.ctrlKey||e.altKey||e.metaKey)return;
 if(['ArrowDown','PageDown','ArrowUp','PageUp',' '].includes(e.key))e.preventDefault();
 if(e.key==='ArrowDown'||e.key==='PageDown')moveFeed(1);
 else if(e.key==='ArrowUp'||e.key==='PageUp')moveFeed(-1);
 else if(e.key===' '){const v=$(`#feed .fi[data-index="${F.active}"] video`);if(v)toggleFeedPlay(v)}
 else if(e.key.toLowerCase()==='m')feedToggleSound();});
const POST={home(){},
 feed(){A.pause();feedInitialize()}};
// hero
async function heroSet(i){HX=i;const t=HF[i];if(!t||!$('#hc'))return;$('#hc').classList.add('sw');await new Promise(r=>setTimeout(r,250));if(!$('#hc'))return;
 $('#hbg').style.cssText=t.cover?`background-image:url(/media/${t.cover});background-size:cover;background-position:center`:`background:${gg(t.genre)}`;
 $('#ht').textContent=t.artist;$('#hsub').textContent=t.title+' · '+t.genre;$('#hart').innerHTML=art(t);document.querySelectorAll('#hdots i').forEach((d,k)=>d.classList.toggle('on',k==i));$('#hc').classList.remove('sw')}
const heroPlay=()=>{const n=lst(HF);play(n,HF[HX].id)},heroArtist=()=>go('artist',HF[HX].artistId);
// player
const fmt=s=>isFinite(s)?Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0'):'0:00';
function play(n,id){if(Date.now()-S.sw<400)return;S.queue=LISTS[n].map(i=>cache[i]).filter(Boolean);S.qi=S.queue.findIndex(t=>t.id==id);load()}
function playAll(n){S.queue=LISTS[n].map(i=>cache[i]).filter(Boolean);S.qi=0;load()}
function parseLrc(s){if(!s)return null;const L=[];let timed=0;for(const ln of s.split('\n')){const m=/^\[(\d+):(\d+(?:\.\d+)?)\](.*)/.exec(ln.trim());if(m){timed=1;L.push({t:+m[1]*60+ +m[2],x:m[3].trim()})}else if(ln.trim())L.push({t:-1,x:ln.trim()})}return L.length?{timed,L}:null}
async function load(){const t=S.queue[S.qi];if(!t)return;S.cur=t;S.lrc=parseLrc(t.lyrics);A.src='/media/'+t.media;A.playbackRate=S.spd;A.play().catch(()=>{});$('#player').style.display='block';$('#pt').textContent=t.title;$('#pr').textContent=t.artist;$('#pa').innerHTML=art(t);
 fetch('/api/play',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:t.id})});
 if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:t.album||'Mzansi Beats',artwork:t.cover?[{src:'/media/'+t.cover,sizes:'512x512'}]:[{src:'/icon.svg',sizes:'512x512',type:'image/svg+xml'}]});
  for(const[a,f]of[['play',()=>A.play()],['pause',()=>A.pause()],['previoustrack',prev],['nexttrack',next],['seekto',e=>{A.currentTime=e.seekTime}]])try{navigator.mediaSession.setActionHandler(a,f)}catch(e){}}
 const c=await colorOf(t);$('#np').style.setProperty('--acc',c);$('#npbg').style.background=`radial-gradient(circle at 50% 22%,${c},transparent 68%)`;
 if(t.kind=='video'){openVideo();return}if($('#np').classList.contains('open'))npRender()}
function step(d){if(!S.queue.length)return;S.qi=(S.qi+d+S.queue.length)%S.queue.length;load()}
function next(){if(S.shuf&&S.queue.length>1){let n;do n=Math.floor(Math.random()*S.queue.length);while(n==S.qi);S.qi=n;load()}else step(1)}
function prev(){if(A.currentTime>3)A.currentTime=0;else step(-1)}
const toggle=()=>A.paused?A.play():A.pause();
A.onplay=A.onpause=()=>{const p=A.paused;$('#pp').textContent=$('#npp').textContent=p?'▶':'⏸';$('#np').classList.toggle('pl',!p)};
A.onended=()=>{if(S.rep==2){A.currentTime=0;A.play();return}if(!S.rep&&!S.shuf&&S.qi==S.queue.length-1)return;next()};
A.ontimeupdate=()=>{if(!A.duration)return;const p=A.currentTime/A.duration;$('#mp').style.width=p*100+'%';$('#ncu').textContent=fmt(A.currentTime);$('#ndu').textContent=fmt(A.duration);const b=$('#wave').children,n=Math.floor(p*b.length);for(let i=0;i<b.length;i++)b[i].classList.toggle('f',i<n);
 if(S.lrc&&S.lrc.timed&&S.tab=='lyrics'){const ps=document.querySelectorAll('.ly p');let c=-1;S.lrc.L.forEach((l,i)=>{if(l.t<=A.currentTime)c=i});ps.forEach((e,i)=>{const on=i==c;if(on&&!e.classList.contains('cur'))e.scrollIntoView({block:'center',behavior:'smooth'});e.classList.toggle('cur',on)})}};
