function npOpen(){const t=S.cur;if(!t)return;if(t.kind=='video')return openVideo();$('#np').classList.add('open');npRender()}
const npClose=()=>$('#np').classList.remove('open');
function npTab(t){S.tab=S.tab==t?'art':t;npRender()}
function wv(t){let h=hs(t.id);return [...Array(64)].map(()=>{h=(h*1103515245+12345)>>>0;return 18+(h>>8)%82})}
function npRender(){const t=S.cur;if(!t)return;$('#npt').textContent=t.title;$('#npa').textContent=t.artist+' · '+t.genre;$('#wave').innerHTML=wv(t).map(h=>`<i style="height:${h}%"></i>`).join('');
 $('#blk').textContent=lk(t);$('#blk').classList.toggle('on',!!t.liked);$('#bsh').classList.toggle('on',!!S.shuf);$('#brp').classList.toggle('on',!!S.rep);$('#brp').textContent=S.rep==2?'🔂':'🔁';$('#byl').classList.toggle('on',S.tab=='lyrics');$('#bqu').classList.toggle('on',S.tab=='queue');
 const m=$('#npmain');m.className=S.tab=='art'?'':'top';
 if(S.tab=='art')m.innerHTML=art(t,'big');
 else if(S.tab=='lyrics')m.innerHTML=S.lrc?`<div class="ly ${S.lrc.timed?'':'plain'}">${S.lrc.L.map(l=>`<p>${esc(l.x)}</p>`).join('')}</div>`:'<p class="mu" style="margin:auto">No lyrics for this track yet.</p>';
 else m.innerHTML=`<div style="width:100%">${S.queue.map((q,i)=>`<div class="qi ${i==S.qi?'cur':''}" draggable="true" data-i="${i}"><div style="width:44px;flex:none">${art(q)}</div><div class="m" onclick="S.qi=${i};load()"><b>${esc(q.title)}</b><div class="mu">${esc(q.artist)}</div></div><button class="ic" onclick="qmove(${i},${i-1})">↑</button>${i!=S.qi?`<button class="ic" onclick="qrm(${i})">✕</button>`:''}</div>`).join('')}</div>`;
 A.ontimeupdate()}
function qmove(a,b){if(a==b||b<0||b>=S.queue.length)return;const c=S.queue[S.qi],[x]=S.queue.splice(a,1);S.queue.splice(b,0,x);S.qi=S.queue.indexOf(c);npRender()}
function qrm(i){const c=S.queue[S.qi];S.queue.splice(i,1);S.qi=S.queue.indexOf(c);npRender()}
function enqueue(id){const t=cache[id];if(!t)return;if(!S.queue.length){S.queue=[t];S.qi=0;load();return}S.queue.splice(S.qi+1,0,t);toast('Playing next');closeM()}
$('#npmain').addEventListener('dragstart',e=>{const q=e.target.closest('.qi');if(q)e.dataTransfer.setData('t',q.dataset.i)});$('#npmain').addEventListener('dragover',e=>{const q=e.target.closest('.qi');if(q){e.preventDefault();document.querySelectorAll('.qi.ov').forEach(x=>x.classList.remove('ov'));q.classList.add('ov')}});
