function sleep(){const a=[0,15,30,60];sleepI=(sleepI+1)%4;clearTimeout(sleepT);const m=a[sleepI];$('#bsl').textContent='😴 '+(m?m+'m':'Off');$('#bsl').classList.toggle('on',!!m);if(m)sleepT=setTimeout(()=>{A.pause();sleepI=0;$('#bsl').textContent='😴 Off';$('#bsl').classList.remove('on');toast('Sleep timer — paused')},m*6e4)}
