const seek=e=>{if(!A.duration)return;const r=$('#wave').getBoundingClientRect();A.currentTime=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*A.duration};
$('#wave').addEventListener('pointerdown',e=>{seek(e);const mv=ev=>seek(ev),up=()=>{removeEventListener('pointermove',mv);removeEventListener('pointerup',up)};addEventListener('pointermove',mv);addEventListener('pointerup',up)});
// swipe down to minimise
(()=>{const np=$('#np');let y0=null,dy=0;np.addEventListener('touchstart',e=>{if(e.target.closest('#wave,#npmain.top,.ly'))return;y0=e.touches[0].clientY;dy=0},{passive:true});
 np.addEventListener('touchmove',e=>{if(y0==null)return;dy=e.touches[0].clientY-y0;if(dy>0){np.style.transition='none';np.style.transform=`translateY(${dy}px)`}},{passive:true});
 np.addEventListener('touchend',()=>{if(y0==null)return;np.style.transition='';np.style.transform='';if(dy>120)npClose();y0=null})})();
// swipe gestures on rows
(()=>{let w=null;const app=$('#app');app.addEventListener('touchstart',e=>{const it=e.target.closest('.it');w=it?{it,x:e.touches[0].clientX,y:e.touches[0].clientY,dx:0,l:0}:null},{passive:true});
 app.addEventListener('touchmove',e=>{if(!w)return;const dx=e.touches[0].clientX-w.x,dy=e.touches[0].clientY-w.y;if(!w.l){if(Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy))w.l=1;else if(Math.abs(dy)>12){w=null;return}}if(w.l){w.dx=dx;w.it.style.transition='none';w.it.style.transform=`translateX(${dx*.5}px)`;w.it.style.background=dx>0?'#e03c3155':'#00774988'}},{passive:true});
 app.addEventListener('touchend',()=>{if(!w||!w.l){w=null;return}const it=w.it;it.style.transition='';it.style.transform='';it.style.background='';S.sw=Date.now();if(w.dx>70)it.querySelector('.lk').click();else if(w.dx<-70)enqueue(it.dataset.id);w=null})})();
