const adm=async b=>{await api('/api/admin',{b});go('admin')},delTrack=async id=>{if(confirm('Delete this track?')){await api('/api/track?id='+id,{m:'DELETE'});go('studio')}};
async function like(id,b){try{const r=await api('/api/like',{b:{id}}),t=cache[id];if(t){t.liked=r.liked?1:0;t.likes=r.likes}const fd=b.closest('.fa');b.textContent=fd?(r.liked?'♥':'♡'):lk(t||{liked:r.liked,likes:r.likes});b.classList.toggle('on',r.liked);document.querySelectorAll(`[data-lc="${id}"]`).forEach(e=>e.textContent=r.likes);document.querySelectorAll(`.it[data-id="${id}"] .lk`).forEach(x=>{x.textContent=lk(t);x.classList.toggle('on',r.liked)});if(S.cur&&S.cur.id==id&&$('#np').classList.contains('open'))npRender();if(r.liked)toast('Added to liked songs')}catch(e){toast(e.message);authModal()}}
