const M=h=>{if(S.route[0]==='feed')pauseFeed();$('#box').innerHTML=h;$('#modal').classList.add('show')},closeM=()=>{$('#modal').classList.remove('show');$('#box').innerHTML='';if(S.route[0]==='feed'&&F.active>=0){const v=$(`#feed .fi[data-index="${F.active}"] video`);v?.play().catch(()=>{})}};
const owns=t=>S.owned.has(t.id)||(S.user&&(S.user.id==t.artistId||S.user.role=='admin')),payBtns=t=>(t.price>0?(owns(t)?`<button onclick="download('${t.id}')">⬇ Download</button>`:S.meta.payments?`<button onclick="buy('${t.id}')">Buy ${R(t.price)}</button>`:''):'')+(t.tip&&S.meta.payments?`<button class="g" onclick="tipModal('${t.artistId}')">💛 Tip</button>`:'');
function cmts(c){S.cm=c;const rp={};c.filter(x=>x.p).sort((a,b)=>a.d-b.d).forEach(x=>(rp[x.p]=rp[x.p]||[]).push(x));
 const one=(x,sub)=>`<div style="margin:10px 0 0 ${sub?'26px':'0'}"><b>${esc(x.name)}</b> <span class="mu">${new Date(x.d).toLocaleDateString('en-ZA')}</span><div>${esc(x.text)}</div><div><button class="ic ${x.liked?'on':''}" style="font-size:13px;padding:2px 6px" onclick="clike('${x.id}',this)">${x.liked?'♥':'♡'}${x.likes?' '+x.likes:''}</button><button class="ic" style="font-size:13px;padding:2px 6px" onclick="replyTo('${x.id}')">Reply</button></div></div>`;
 return c.filter(x=>!x.p).map(x=>one(x,0)+(rp[x.id]||[]).map(y=>one(y,1)).join('')).join('')||'<p class="mu">No comments yet.</p>'}
async function openVideo(feed){const t=S.cur;if(!t)return;S.reply=null;const c=await api('/api/comments?id='+t.id);if(t.kind=='video'&&!feed)A.pause();
 M(`${t.kind=='video'&&!feed?`<video src="/media/${t.media}" controls autoplay playsinline></video>`:art(t,'').replace('class="art "','class="art" style="height:200px;font-size:16px"')}<h2 style="margin:0">${esc(t.title)}</h2><div class="mu">${esc(t.artist)} · ${esc(t.genre)} · ${t.province}</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="g ${t.liked?'on':''}" onclick="like('${t.id}',this)">${lk(t)}</button><button onclick="share('${t.id}')">Share</button>${payBtns(t)}<button class="g" onclick="closeM()">Close</button></div><div id="rp" class="mu"></div><textarea id="ct" rows="2" placeholder="Add a comment…"></textarea><button class="g" onclick="comment('${t.id}',${feed?1:0})">Post</button><div id="cl">${cmts(c)}</div>`)}
function replyTo(id){const x=S.cm.find(c=>c.id==id);S.reply=x;$('#rp').innerHTML=`Replying to <b>${esc(x.name)}</b> · <a style="cursor:pointer;color:var(--gold)" onclick="S.reply=null;$('#rp').textContent=''">cancel</a>`;$('#ct').focus()}
