function authModal(reg){const o=S.meta.provinces.map(p=>`<option>${p}</option>`).join('');M(`<h2 style="margin:0">${reg?'Join Mzansi Beats':'Welcome back'}</h2>${reg?'<input id="an" placeholder="Name or artist name">':''}<input id="ae" type="email" placeholder="Email"><input id="ap" type="password" placeholder="Password (6+ chars)">${reg?`<select id="apr">${o}</select><label><input type="checkbox" id="aa" style="width:auto"> I'm a musician</label>`:''}<div id="er" style="color:var(--red)"></div><button onclick="doAuth(${reg?1:0})">${reg?'Create account':'Sign in'}</button><button class="g" onclick="authModal(${reg?0:1})">${reg?'Have an account? Sign in':'New here? Join free'}</button>`)}
async function doAuth(reg){try{const r=await api(reg?'/api/register':'/api/login',{b:{name:$('#an')?.value,email:$('#ae').value,password:$('#ap').value,province:$('#apr')?.value,artist:$('#aa')?.checked}});S.tok=r.token;S.user=r.user;localStorage.mb_tok=r.token;closeM();afterAuth();toast('Sawubona, '+r.user.name);go(S.route[0],S.route[1])}catch(e){$('#er').textContent=e.message}}
const logout=()=>{S.tok=S.user=null;afterAuth();$('#bdg').style.display='none';localStorage.removeItem('mb_tok');closeM();go('home')},becomeArtist=async()=>{S.user=await api('/api/profile',{b:{becomeArtist:1}});closeM();go('studio')};
addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e});const installApp=()=>{deferred&&deferred.prompt();closeM()};
function profileModal(){const u=S.user;M(`<h3>Profile</h3>${u.role!='listener'?`<input id="pn" value="${esc(u.artist)}" placeholder="Artist name">`:''}<label class="mu">Profile photo (JPG/PNG/WebP · max 2 MB)</label><input id="pavatar" type="file" accept="image/jpeg,image/png,image/webp"><textarea id="pb" rows="3" placeholder="Bio">${esc(u.bio)}</textarea><select id="pp2">${S.meta.provinces.map(p=>`<option ${u.province==p?'selected':''}>${p}</option>`).join('')}</select>${u.role!='listener'?`<label><input type="checkbox" id="pm" style="width:auto" ${u.monetize?'checked':''}> Enable monetization (ZAR)</label><input id="ppr" type="number" min="0" value="${u.price}" placeholder="Default price (R)">`:''}<button onclick="saveProfile()">Save</button>`)}
async function saveProfile(){try{S.user=await api('/api/profile',{b:{artist:$('#pn')?.value,bio:$('#pb').value,province:$('#pp2').value,monetize:$('#pm')?.checked,price:$('#ppr')?.value}});
 const file=$('#pavatar')?.files[0];if(file){if(file.size>2*1024*1024)throw Error('Profile photo must be smaller than 2 MB');
 const resp=await fetch('/api/avatar',{method:'POST',headers:{'Authorization':'Bearer '+S.tok,'Content-Type':file.type},body:file});
 const result=await resp.json();if(!resp.ok)throw Error(result.error||'Photo upload failed');S.user.avatar=result.avatar;}
 closeM();toast('Profile updated');go(...S.route)}catch(e){toast(e.message)}}
function uploadModal(){M(`<h3>Upload</h3><input id="ut" placeholder="Track title"><input id="uab" placeholder="Album / EP name (optional)"><select id="ug">${S.meta.genres.map(g=>`<option>${g}</option>`).join('')}</select><select id="up">${S.meta.provinces.map(g=>`<option ${S.user.province==g?'selected':''}>${g}</option>`).join('')}</select><select id="uy"><option value="single">Single</option><option value="album">Album track</option><option value="video">Music video</option></select><select id="ul"><option value="en">English</option><option value="zu">isiZulu</option><option value="xh">isiXhosa</option><option value="af">Afrikaans</option><option value="st">Sesotho</option><option value="tn">Setswana</option></select>${S.user.monetize?'<input id="upr" type="number" min="0" placeholder="Price in ZAR (0 = free)">':''}<label class="mu">Audio / video file</label><input type="file" id="um" accept="audio/*,video/mp4,video/webm"><label class="mu">Cover art (optional)</label><input type="file" id="uc" accept="image/*"><textarea id="ulr" rows="3" placeholder="Lyrics (optional). Synced: [00:12.5]First line"></textarea><div class="prog"><div id="upg"></div></div><div id="us" class="mu"></div><button id="ub" onclick="doUpload()">Upload</button>`)}
function doUpload(){const m=$('#um').files[0];if(!m||!$('#ut').value)return toast('Title and file required');const f=new FormData();for(const[k,v]of[['title','ut'],['album','uab'],['genre','ug'],['province','up'],['type','uy'],['lang','ul'],['lyrics','ulr']])f.append(k,$('#'+v).value);if($('#upr'))f.append('price',$('#upr').value);if($('#uc').files[0])f.append('cover',$('#uc').files[0]);f.append('media',m);
 const x=new XMLHttpRequest();x.open('POST','/api/upload');x.setRequestHeader('Authorization','Bearer '+S.tok);$('#ub').disabled=true;x.upload.onprogress=e=>{if(e.lengthComputable){const p=e.loaded/e.total*100;$('#upg').style.width=p+'%';$('#us').textContent=Math.round(p)+'% uploaded'}};
 x.onload=()=>{if(x.status==200){closeM();toast('Published!');go('studio')}else{$('#us').textContent=JSON.parse(x.responseText).error;$('#ub').disabled=false}};x.onerror=()=>{$('#us').textContent='Network error';$('#ub').disabled=false};x.send(f)}

