async function notifModal(){await pollNotifs();const L={like:n=>`❤️ <b>${esc(n.name)}</b> liked “${esc(n.title||'your track')}”`,follow:n=>`➕ <b>${esc(n.name)}</b> started following you`,comment:n=>`💬 <b>${esc(n.name)}</b> commented on “${esc(n.title||'your track')}”: ${esc(n.text)}`,reply:n=>`↩️ <b>${esc(n.name)}</b> replied: ${esc(n.text)}`,clike:n=>`👍 <b>${esc(n.name)}</b> liked your comment`,sale:n=>`💰 <b>${esc(n.name)}</b> bought “${esc(n.title||'a track')}” (${esc(n.text)})`,tip:n=>`💛 <b>${esc(n.name)}</b> tipped you ${esc(n.text)}`,vlike:n=>`♥ <b>${esc(n.name)}</b> liked your video`,vcomment:n=>`💬 <b>${esc(n.name)}</b> commented: ${esc(n.text)}`,vreply:n=>`↩️ <b>${esc(n.name)}</b> replied: ${esc(n.text)}`,newvideo:n=>`▶ <b>${esc(n.name)}</b> shared a new video`};
 M(`<h3>Notifications</h3>${S.nf.map(n=>`<div style="padding:8px 0;border-bottom:1px solid var(--line);${n.read?'opacity:.6':''}">${(L[n.type]||(()=>''))(n)}${n.t&&n.t.includes(':')?`<button class="g" onclick="closeM();viewVideo('${esc(n.t)}')">View video ↗</button>`:''}<div class="mu">${new Date(n.d).toLocaleString('en-ZA')}</div></div>`).join('')||'<p class="mu">Nothing yet.</p>'}<button class="g" onclick="closeM()">Close</button>`);await api('/api/notifs/read',{b:{}});$('#bdg').style.display='none'}
